arguments.command:
python3 -c "
import json
from datetime import datetime

with open('/app/benchmark/source_data.json') as f:
    data = json.load(f)

def parse_date(d):
    if '-' in d:
        return datetime.strptime(d, '%Y-%m').toordinal()
    return datetime(int(d), 7, 1).toordinal()

count_early = 0
count_late = 0
labels_late = []

for track_key in ['research_milestones', 'industry_milestones', 'regulation_milestones']:
    for e in data[track_key]['data']:
        d = parse_date(e['date'])
        if d < parse_date('2018-01'):
            count_early += 1
        if d >= parse_date('2023-01') and d < parse_date('2025-01'):
            count_late += 1
            labels_late.append(f'{e[\"label\"]} ({e[\"date\"]})')

print(f'Early (2010-2017): {count_early}')
print(f'Late (2023-2024): {count_late}')
print('Late events:')
for l in labels_late:
    print(f'  - {l}')
"

